values ('bf86e721-1ef4-4586-b22c-a030b04ddc15', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "8d2a4aac-c5e0-4127-893b-3fe2ee940197", "heading": "Dates & Rates", "manual_dates_text": "Oct 11 - 18, 2025", "manual_tiers": [{"name": "Dorm", "price": "$795"}, {"name": "Triple", "price": "$945"}, {"name": "Double", "price": "$1,095"}, {"name": "Single", "price": "$1,645"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/the-art-of-being-retreat-natalia-chaverri-2/?form=1&lang=en"}'::jsonb)
