insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('bf86e721-1ef4-4586-b22c-a030b04ddc15', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>The Art of Being: A Retreat For Those Ready to Thrive.</strong></p><p>Discover the transformative power of choosing yourself at this Costa Rica retreat.</p><p>In a world that demands constant doing, \u201cThe Art of Being\u201d invites you to remember who you are beneath it all. Design your perfect escape with yoga, mindful workshops, spa treatments, nature adventures, or pure relaxation\u2026 this is your moment to reconnect with what truly matters.</p><p>When you give yourself permission to just BE, everything shifts. Your personalized retreat experience awaits in paradise.</p><p>Anamaya provides the perfect escape to reconnect with yourself while stepping away from life\u2019s relentless pace and urban chaos. Throughout the week, Natalia will guide you through carefully curated workshops designed for souls ready to break free from limiting routines and rediscover what truly matters.</p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('bf86e721-1ef4-4586-b22c-a030b04ddc15', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Partner Yoga Workshop", "price": "$90", "note": "90-minute workshop"}, {"name": "Bio-Creation Workshop", "price": "$90", "note": "90-minute workshop"}, {"name": "Awakening the Senses Workshop", "price": "$90", "note": "90-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('bf86e721-1ef4-4586-b22c-a030b04ddc15', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Partner Yoga Workshop</h3><p><em>90-minute workshop &mdash; $90</em></p><p>There&#8217;s something magical about sharing your practice with another person. In this playful workshop, you&#8217;ll flow through sequences designed for two, discovering new depths in familiar poses while building trust and connection. Expect laughter, supported stretches, creative balances, and those beautiful moments when two people move as one. As they say, <em>&#8220;Unity is strength&#8221;</em> \u2013 and you&#8217;ll feel that power firsthand.</p><h3>Bio-Creation Workshop</h3><p><em>90-minute workshop &mdash; $90</em></p><p>Bio-creation is the art of connecting with your highest self and letting your inner potential shine. Grounded in earth energy yet reaching toward infinite possibility, we&#8217;ll dive deep into your soul&#8217;s true desires and create a roadmap for the life you&#8217;ve been dreaming of. Through intentional practices, you&#8217;ll learn to shift your emotional frequency toward joy, abundance, and wellness while releasing old patterns that no longer serve you. Discover the essence of who you truly are and remember this truth: a peaceful mind is a powerful mind.</p><h3>Awakening the Senses Workshop</h3><p><em>90-minute workshop &mdash; $90</em></p><p>Take an extraordinary journey inward as we awaken your inner light through the gateway of the senses. Through mindful experiences with food, music, movement, essential oils, and sacred silence, you&#8217;ll rediscover the profound connection between your senses and your soul. This immersive meditation becomes a conscious celebration of life itself, bringing you fully into the magic of the present moment and the vibrant being you truly are.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('bf86e721-1ef4-4586-b22c-a030b04ddc15', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/retreat-on-pool-edge-1200px-300x300-a16df9ae.jpg", "alt": "The Art of Being \u2013 Natalia Chaverri"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/yoga_mg_2881-800x600-1-300x300-31d7e222.jpg", "alt": "The Art of Being \u2013 Natalia Chaverri"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "The Art of Being \u2013 Natalia Chaverri"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/bf86e721-1ef4-4586-b22c-a030b04ddc15/gallery/anamaya-guests-on-the-beach-300x300-bba25b6e.jpg", "alt": "The Art of Being \u2013 Natalia Chaverri"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/d6e8e73e-71a9-4e07-89c1-802d892b4954/gallery/psx_20200926_135655-300x300-3a0c7299.jpg", "alt": "The Art of Being \u2013 Natalia Chaverri"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/bf86e721-1ef4-4586-b22c-a030b04ddc15/gallery/foto-nati--800x800-2f791b4a.jpg", "alt": "The Art of Being \u2013 Natalia Chaverri"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('bf86e721-1ef4-4586-b22c-a030b04ddc15', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Natalia Chaverri", "bio_html": "<p>Meet Natalia, your transformational guide for \u201cThe Art of Being\u201d retreat in Costa Rica. A devoted healer with over 25 years of experience, this passionate Costa Rican has dedicated her life to the mysteries of well-being and the beauty of holistic healing.</p><p>Beginning her journey at just 16, Natalia became a certified Holistic Balance Instructor and Yoga Teacher at the renowned GAIA Holistic Institute in San Jos\u00e9. Her extensive training spans Hatha Yoga, meditation, sound healing, Reiki, Biocreation, reflexology, and holistic massage. She later deepened her practice through 300-hour Hatha Yoga and 200-hour Anusara Yoga teacher trainings with international instructors.</p><p>Natalia''s true calling emerged in 2005 when she discovered aquatic bodywork. As a certified Watsu\u00ae and Aquadinamic Instructor, she founded Watsu\u00ae Costa Rica and the Aquatic Therapy Institute of Costa Rica, becoming a pioneer in water-based healing throughout Central America.</p><p>Her global studies have taken her from Thailand (Thai massage and Chi Nei Tsang) to Bali (yoga immersion), while her Master\u2019s degree in Therapeutic Exercise from Barcelona perfectly blends her physical therapy background with yoga and somatic movement.</p><p>At Anamaya Resort, Natalia has guided over nine transformational retreats, offering yoga, meditation, partner yoga, sound healing, Biocreation, and her signature \u201cAwakening the Senses\u201d workshop. This global soul divides her time between Costa Rica and Spain, continuously learning from diverse cultures and sharing her gifts with love, joy, and presence.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/bf86e721-1ef4-4586-b22c-a030b04ddc15/gallery/foto-nati--800x800-2f791b4a.jpg"}'::jsonb)
on conflict do nothing;
