values ('4f8f87ac-cc57-436c-ac07-e230bbcf957b', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "7d801a00-0851-475f-ad97-71bb7b75f86a", "heading": "Dates & Rates", "manual_dates_text": "March 6 - 13, 2027", "manual_tiers": [{"name": "Dorm", "price": "$1,095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/pura-vida-costa-rica-retreat-kimberly-manthey/?form=1&lang=en"}'::jsonb)
