insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('4f8f87ac-cc57-436c-ac07-e230bbcf957b', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Explore & Restore: A 2-Part Workshop Series to Reclaim Your Energy and Strengthen Your Mental Health</h3><p><em>60-minute workshop &mdash; $90</em></p><p><strong>Practice self-compassion. Embrace change with clarity. Build the kind of resilience that lasts.</strong></p><p>If you\u2019ve been running on empty, questioning your capacity, or feeling stuck in patterns that drain you, this workshop series is for you.</p><p>Led by Kimberly, these two one-hour workshops blend real-world tools with reflective prompts to help you shift how you show up for yourself, especially when life feels overwhelming.</p><p><strong>You\u2019ll walk away with:</strong></p><ul><li>10 practices that support mental clarity and emotional strength</li><li>7 simple, natural ways to boost your energy\u2014no burnout required</li><li>Tools to stop wasting your time on what doesn\u2019t matter</li><li>A mindset shift that turns setbacks into momentum</li><li>New language for how you speak to yourself and hold your power</li></ul><p>You don\u2019t have to attend both sessions, but each one offers a different layer of insight and support. Show up to one or both, and leave with practical strategies and a clearer head.</p><p><strong>Come as you are. Leave with a lighter load and a stronger sense of self.</strong></p><h3>Yoga Nidra</h3><p><em>60-minute workshop &mdash; $35</em></p><p>Yoga nidra, also known as yogic sleep, is a guided meditation practice that induces a state of consciousness between waking and sleeping. It&#8217;s a powerful tool for deep relaxation, stress reduction, and improved sleep quality.</p><p>During a yoga nidra session, you will lie in Savasana (corpse pose) and follow a series of guided instructions that lead you through various stages of awareness and relaxation.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('4f8f87ac-cc57-436c-ac07-e230bbcf957b', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Kimberly Manthey", "bio_html": "<p>Kimberly Manthey, founder of Dirty Feet Yoga and Wellness has been instructing yoga teachers and everyday people for over 25 years. Pulling from multiple styles of Yoga, Kimberly\u2019s mission is to bring together the body, mind, and spirit each and every time she crosses your path.</p><p>She began yoga in 1997 as a means of stress reduction when her high powered corporate career, grief over the death of her father, and a brand new marriage all collided and caused her to re-evaluate her purpose.</p><p>In addition to leading several yoga retreats nationwide, and internationally, she has coached corporate sales teams, schools, and hundreds of individuals, and brings with her, a unique blend of humor and story telling. Comfortable instructing to all levels of yoga, her classes can range from gentle and soothing to powerful and dynamic.</p><p>She looks forward to meeting you wherever you are on your journey in life. Namaste!</p><h3>Certifications &amp; Qualifications</h3><ul><li>Experienced Registered Yoga Teacher with the Yoga Alliance</li><li>Continuing Education Provider with Yoga Alliance</li><li>Certified Advanced Yoga and Meditation Teacher</li><li>Certified Wellness Coach through the International Association of Wellness Professionals</li><li>Over 25 years of hands-on teaching experience.</li></ul>"}'::jsonb)
on conflict do nothing;
