values ('316d6f22-e180-49d4-8555-0823d5ff2752', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "7d801a00-0851-475f-ad97-71bb7b75f86a", "heading": "Dates & Rates", "manual_dates_text": "March 6 - 13, 2027", "manual_tiers": [{"name": "Dorm", "price": "$1,095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/pura-vida-costa-rica-retreat-kimberly-manthey/?form=1&lang=en"}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('316d6f22-e180-49d4-8555-0823d5ff2752', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p>A Retreat for a Much Deserved Reset.</p><p>You keep telling yourself that you\u2019ll take time for YOU \u2013 when the work slows down, when the kids need you less, when life isn\u2019t so demanding. But let\u2019s be real: that <em>someday</em> never comes unless you claim it.</p><p><strong>This is your moment.</strong></p><p>If life has been asking too much of you lately, this retreat offers the pause your nervous system has been craving. With over 25 years of experience and a loyal following at Anamaya, Kimberly will create a haven where you can finally exhale, reflect, and reset.</p><p>This retreat is for anyone who\u2019s been holding it all together and is ready to feel supported, energized, and more like themselves again.</p><p><strong>Come as you are \u2013 and leave feeling Pura Vida.</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
