insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('58ba79c2-84ef-4dfe-82b4-e56059112124', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "7a26a594-f77e-448b-8b6c-5b036537f778", "heading": "Dates & Rates", "manual_dates_text": "Jan 30 - Feb 6, 2027", "manual_tiers": [{"name": "Dorm", "price": "$1,095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.com/rg-calendar/"}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('58ba79c2-84ef-4dfe-82b4-e56059112124', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>You Know That Version of You Who Feels Alive, Clear, and Fully Here?</strong></p><p>They\u2019re not gone \u2013 just buried under everything you\u2019ve been carrying, and this retreat is where you finally set it all down. For one week in Costa Rica, you step out of the noise and back into yourself.</p><p>Dagmar\u2019s dynamic morning vinyasa wakes up what\u2019s been asleep. Her restorative evening yin gives you permission to exhale. And the space in between \u2013 the ocean views, the nourishing food, the jungle air \u2013 does something to a person that\u2019s almost impossible to explain until you\u2019ve felt it.</p><p>This retreat is fully yours to shape. Add spa treatments, Costa Rican adventures, or simply let the days unfold at whatever pace your body is asking for. Your week, your way.</p><p><strong>Leave grounded, energized, and reconnected to the spark that\u2019s been waiting for you.</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('58ba79c2-84ef-4dfe-82b4-e56059112124', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Conscious Communication Workshop", "price": "$70", "note": "90-minute workshop"}, {"name": "Ecstatic Dance Workshop", "price": "$70", "note": "90-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('58ba79c2-84ef-4dfe-82b4-e56059112124', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Conscious Communication Workshop</h3><p><em>90-minute workshop &mdash; $70</em></p><p><strong>There&#8217;s a version of every conversation you didn&#8217;t have.</strong></p><p>The thing you almost said. The need you talked yourself out of expressing. The moment you went quiet instead of honest &#8211; not because you didn&#8217;t have the words, but because somewhere along the way you learned it was safer not to use them.</p><p>That habit has a cost. Relationships that stay surface-level. Resentment that builds without a name. A low-grade exhaustion from editing yourself before you even open your mouth.</p><p>This workshop is 90 minutes of unlearning that.</p><p>You&#8217;ll walk away with real, practical tools for saying what you mean with clarity and care &#8211; no over-explaining, no shutdown, no wondering afterward if you handled it wrong. Language for asking for what you need. Tools for staying grounded when conversations get hard. And a clearer picture of where you hold back and why.</p><h3>Ecstatic Dance Workshop</h3><p><em>90-minute workshop &mdash; $70</em></p><p><strong>No steps to learn. No mirrors. No performing.</strong></p><p>Just music, movement, and 90 minutes of full permission to be completely in your body.</p><p>Ecstatic Dance is a movement meditation. The music builds slowly, the thinking quiets, and something underneath all that effort finally gets to breathe. Most people walk in skeptical and leave wondering why they don&#8217;t do this every week.</p><p>You don&#8217;t need to dance well. You don&#8217;t even need to like dancing. You just need to be willing to get out of your head for a little while.</p><p>You&#8217;ll leave lighter, looser, and more at home in yourself than you&#8217;ve felt in a long time.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('58ba79c2-84ef-4dfe-82b4-e56059112124', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Dagmar Spremberg", "bio_html": "<p><strong>Reignite Your Inner Spark with Dagmar Spremberg</strong></p><p>Dagmar Spremberg made the kind of leap most people only dream about. She left city life in LA and New York, followed something deeper, and landed in Montezuma, Costa Rica \u2013 where she founded Montezuma Yoga and built a life that actually matched who she was.</p><p>That journey is woven into everything she teaches.</p><p>A 500-hour E-RYT trained in Anusara, Vinyasa Flow, and Yin Yoga, and mentored by master teachers including Elena Brower and Rod Stryker, Dagmar works with the breath as the doorway to intuition and inner knowing. Her morning flows are energizing and accessible. Her evening yin sessions are deeply restorative. Both are open to all levels, and both carry the same quiet message: you already have everything you need. This week is just about remembering it.</p><p>You\u2019ll leave with more than a yoga practice. You\u2019ll leave with the tools to keep showing up for yourself long after you\u2019re back in real life.</p>", "photo_url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-leader-photos/staging/58ba79c2-84ef-4dfe-82b4-e56059112124/leader/49171b107137e9a6f27ad4128395cffb041b5dc9eb0677119b3b659ce06e0457-db55b599.jpg"}'::jsonb)
on conflict do nothing;
